import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"29. Vad är en databas inte?","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/29-vad-ar-en-databas-inte.md","filePath":"sv/chapters/29-vad-ar-en-databas-inte.md"}'),s={name:"sv/chapters/29-vad-ar-en-databas-inte.md"};function i(l,a,d,o,p,k){return t(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="_29-vad-ar-en-databas-inte" tabindex="-1">29. Vad är en databas inte? <a class="header-anchor" href="#_29-vad-ar-en-databas-inte" aria-label="Permalink to &quot;29. Vad är en databas inte?&quot;">​</a></h1><p>Vi började den här boken med en enkel uppgift: att hålla reda på information.</p><p>En kund har ett namn. En bok har en titel. En beställning hör till en kund och innehåller produkter. Genom att bestämma vad dessa uppgifter betyder och hur de hör ihop har vi byggt en databas som kan besvara allt mer avancerade frågor.</p><p>Vi har också sett hur en databas kan hjälpa oss att upprätthålla regler, bevara historik och hantera förändringar.</p><p>Men ju mer vi lär oss att göra med SQL, desto viktigare blir en annan fråga:</p><p><strong>Vad kan en databas inte göra åt oss?</strong></p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="databasen-ar-inte-verkligheten" tabindex="-1">Databasen är inte verkligheten <a class="header-anchor" href="#databasen-ar-inte-verkligheten" aria-label="Permalink to &quot;Databasen är inte verkligheten&quot;">​</a></h3><p>Vi kan börja med en rad ur bokhandelns produkttabell:</p><table tabindex="0"><thead><tr><th>id</th><th>title</th><th style="text-align:right;">price</th><th style="text-align:right;">stock</th></tr></thead><tbody><tr><td>1</td><td>Vägen hem</td><td style="text-align:right;">200.00</td><td style="text-align:right;">12</td></tr></tbody></table><p>Raden säger att produkten med id <code>1</code> heter <code>Vägen hem</code>, kostar 200 kronor och har ett lagersaldo på 12 exemplar.</p><p>Men den <strong>är inte boken</strong>. Den är en representation av något i bokhandelns verksamhet.</p><p>Om en anställd hittar ytterligare fem exemplar på lagret förändras inte databasen automatiskt. Någon eller något behöver registrera förändringen.</p><p>Och om databasen säger att det finns 12 exemplar trots att det bara finns 11 på hyllan är det verkligheten och databasen som inte längre stämmer överens.</p><p>Det här är ingen liten teknisk detalj. Det är en grundläggande skillnad mellan <strong>ett sakförhållande</strong> och <strong>vår beskrivning av det</strong>.</p><h3 id="en-datatyp-bestammer-inte-betydelsen" tabindex="-1">En datatyp bestämmer inte betydelsen <a class="header-anchor" href="#en-datatyp-bestammer-inte-betydelsen" aria-label="Permalink to &quot;En datatyp bestämmer inte betydelsen&quot;">​</a></h3><p>Vi kan lagra priset som <code>DECIMAL(10, 2)</code> och lagersaldot som <code>INTEGER</code>.</p><p>Det hjälper oss att bestämma vilka slags värden kolumnerna kan innehålla.</p><p>Men det talar inte om för oss vad <strong>pris</strong> egentligen betyder.</p><p>Är det priset inklusive moms? Gäller det i butik eller på webbplatsen? Är det ordinarie pris eller kampanjpris?</p><p>På samma sätt kan <code>stock = 12</code> betyda tolv fysiska exemplar på lagret – men kanske inte tolv exemplar som är tillgängliga för nya beställningar. Några kan redan vara reserverade.</p><p>Datatyper beskriver hur värden kan representeras och behandlas. <strong>Betydelsen behöver vi definiera utifrån sammanhanget.</strong></p><h3 id="en-query-kan-ge-ratt-svar-pa-fel-fraga" tabindex="-1">En Query kan ge rätt svar på fel fråga <a class="header-anchor" href="#en-query-kan-ge-ratt-svar-pa-fel-fraga" aria-label="Permalink to &quot;En Query kan ge rätt svar på fel fråga&quot;">​</a></h3><p>Vi har lärt oss att skriva Queries som räknar, filtrerar och sammanfattar.</p><p>Anta att bokhandeln vill veta sin omsättning.</p><p>Vi kan skriva:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    SUM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(quantity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unit_price) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> total_amount</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> order_items;</span></span></code></pre></div><p>SQL kan beräkna summan utan problem.</p><p>Men vad har vi egentligen räknat?</p><p>Vi har summerat orderradernas registrerade värden. Vi har inte undersökt om beställningarna betalats, avbrutits eller returnerats. Vi har inte heller bestämt hur rabatter och moms ska hanteras.</p><p>Beräkningen kan vara <strong>tekniskt korrekt</strong> och ändå besvara en annan fråga än den verksamheten avsåg.</p><p>Databasen kan utföra den beräkning vi beskriver. Den kan inte själv avgöra vilken definition av omsättning vi borde använda.</p><h3 id="databasen-ar-inte-applikationen" tabindex="-1">Databasen är inte applikationen <a class="header-anchor" href="#databasen-ar-inte-applikationen" aria-label="Permalink to &quot;Databasen är inte applikationen&quot;">​</a></h3><p>Vi har använt databasen för att registrera beställningar och minska lagersaldon.</p><p>Men ett köp är mer än dessa förändringar.</p><p>Kunden ska kunna välja varor, förstå priset, genomföra betalning och få besked om vad som händer. Bokhandeln kan behöva kontakta leverantörer, organisera leverans och hantera returer.</p><p>Delar av detta innebär att läsa eller förändra data. Andra delar handlar om <strong>arbetsflöden, beslut och kommunikation med människor eller andra system</strong>.</p><p>En databas kan stödja sådana processer. Det betyder inte att alla processer bör byggas in i databasen.</p><p>Det är ofta bättre att låta databasen ansvara för informationens struktur och integritet, medan applikationen organiserar hur verksamhetens handlingar genomförs.</p><p>Gränsen är inte absolut. Vi har redan sett att en verksamhetsregel ibland behöver uttryckas i både applikationen och databasen.</p><h3 id="databasen-ar-inte-en-garanti-for-sanningen" tabindex="-1">Databasen är inte en garanti för sanningen <a class="header-anchor" href="#databasen-ar-inte-en-garanti-for-sanningen" aria-label="Permalink to &quot;Databasen är inte en garanti för sanningen&quot;">​</a></h3><p>Vi kan skydda en kolumn med <code>NOT NULL</code>, <code>UNIQUE</code> och <code>CHECK</code>.</p><p>Det ger viktiga garantier, men bara för de regler vi faktiskt har formulerat.</p><p>Vi kan exempelvis förhindra ett negativt lagersaldo:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Ändå kan databasen innehålla ett felaktigt positivt värde.</p><p>En databas kan kontrollera att data följer en modell. Den kan inte på egen hand kontrollera att <strong>modellen och uppgifterna motsvarar verkligheten</strong>.</p><p>Därför behöver vi också människor, källor, rutiner och kvalitetsarbete.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="modellen-valjer-vad-vi-ser" tabindex="-1">Modellen väljer vad vi ser <a class="header-anchor" href="#modellen-valjer-vad-vi-ser" aria-label="Permalink to &quot;Modellen väljer vad vi ser&quot;">​</a></h3><p>I en databasmodell behöver vi bestämma vilka företeelser som ska ha egna tabeller, vilka egenskaper de har och vilka relationer som är viktiga.</p><p>Det innebär också att vi väljer bort något.</p><p>Bokhandelns modell beskriver kunder, produkter, författare och beställningar. Den säger däremot mycket lite om varför en kund väljer en viss bok, vad läsaren upplever eller hur en anställd bedömer en bok som litteratur.</p><p>Det är inte nödvändigtvis en brist. Modellen är byggd för vissa ändamål.</p><p>Men vi bör komma ihåg att <strong>det som inte finns i modellen inte automatiskt är oviktigt</strong>.</p><p>En databas är alltid en avgränsad beskrivning av verkligheten.</p><h3 id="verksamhetsregler-ar-inte-alltid-databasregler" tabindex="-1">Verksamhetsregler är inte alltid databasregler <a class="header-anchor" href="#verksamhetsregler-ar-inte-alltid-databasregler" aria-label="Permalink to &quot;Verksamhetsregler är inte alltid databasregler&quot;">​</a></h3><p>Vi kan uttrycka många regler med nycklar och begränsningar:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (quantity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Det säger att en orderrad ska innehålla ett positivt antal.</p><p>Men tänk att bokhandeln har regeln att en kund får reservera högst tre exemplar av en efterfrågad bok under en kampanj.</p><p>Gäller begränsningen per beställning, per kund, per dygn eller för hela kampanjperioden? Räknas tidigare annullerade beställningar?</p><p>Innan vi kan implementera regeln måste vi förstå vad den betyder.</p><p>Vissa regler kan uttryckas direkt i databasens struktur. Andra behöver kontroller över flera händelser eller sammanhang och måste hanteras i transaktioner, applikationslogik eller särskilda processer.</p><p>Databasen kan hjälpa oss att upprätthålla ett beslut. Den kan inte fatta alla <strong>begreppsliga beslut</strong> åt oss.</p><h3 id="historik-ar-inte-samma-sak-som-en-andrad-rad" tabindex="-1">Historik är inte samma sak som en ändrad rad <a class="header-anchor" href="#historik-ar-inte-samma-sak-som-en-andrad-rad" aria-label="Permalink to &quot;Historik är inte samma sak som en ändrad rad&quot;">​</a></h3><p>Vi har sett att en produkt kan få ett nytt pris:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 225</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">00</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Nu beskriver <code>products.price</code> det aktuella priset.</p><p>Men instruktionen säger inte varför priset förändrades, vem som fattade beslutet eller vilket pris som gällde vid en tidigare tidpunkt.</p><p>För att besvara sådana frågor behöver vi <strong>modellera historiken</strong>: exempelvis orderradens pris vid köptillfället, tidsperioder för en prislista eller en logg över förändringar.</p><p>Historik uppstår alltså inte automatiskt bara för att vi använder ett databassystem som kan spara och förändra data.</p><p>Vi behöver bestämma <strong>vilka förändringar som är meningsfulla att bevara</strong>.</p><h3 id="en-view-ar-ett-perspektiv-inte-en-ny-verklighet" tabindex="-1">En View är ett perspektiv, inte en ny verklighet <a class="header-anchor" href="#en-view-ar-ett-perspektiv-inte-en-ny-verklighet" aria-label="Permalink to &quot;En View är ett perspektiv, inte en ny verklighet&quot;">​</a></h3><p>Vi lärde oss att Views kan ge namn åt återanvändbara Queries och fungera som logiska modeller.</p><p>En View kan visa produkter tillsammans med produkttyper, eller sammanfatta lagervärden.</p><p>Men den kan inte göra sin information sannare bara genom att presentera den tydligare.</p><p>Två Views kan utgå från samma tabeller och ändå ge olika resultat därför att de använder olika urval, grupperingar eller definitioner.</p><p>Det betyder inte att en av dem måste vara fel. De kanske beskriver olika perspektiv.</p><p>Vi behöver kunna fråga oss <strong>vilka antaganden som ligger bakom varje representation</strong>.</p><h3 id="det-gar-inte-att-fraga-fram-information-som-saknas" tabindex="-1">Det går inte att fråga fram information som saknas <a class="header-anchor" href="#det-gar-inte-att-fraga-fram-information-som-saknas" aria-label="Permalink to &quot;Det går inte att fråga fram information som saknas&quot;">​</a></h3><p>En Query kan vara hur välskriven som helst, men den kan inte återställa ett sakförhållande som aldrig registrerades och inte kan härledas från annan information.</p><p>Om vi bara sparar produktens nuvarande pris kan vi inte i efterhand säkert avgöra vad det kostade förra året.</p><p>Om vi bara sparar ett kundnamn utan en tillförlitlig identifierare kan vi inte alltid avgöra om två poster beskriver samma person.</p><p>Och om vi bara sparar försäljning per månad kan vi inte återskapa varje enskild orderrad.</p><p>Det är därför datamodellering påverkar <strong>vilka frågor som över huvud taget går att besvara senare</strong>.</p><h3 id="lagring-ar-inte-forstaelse" tabindex="-1">Lagring är inte förståelse <a class="header-anchor" href="#lagring-ar-inte-forstaelse" aria-label="Permalink to &quot;Lagring är inte förståelse&quot;">​</a></h3><p>En dataplattform kan samla information från bokhandelns webbplats, kassasystem, lager och leverantörer.</p><p>Men när data förs samman behöver vi fortfarande förstå vad de olika systemen menar.</p><p>Två system kan använda samma ord för olika saker. Eller olika ord för samma företeelse.</p><p>Det är möjligt att skriva SQL som tekniskt förenar deras uppgifter, utan att de därför har blivit <strong>begreppsligt jämförbara</strong>.</p><p>En större mängd data ger inte automatiskt bättre förståelse.</p><p>Vi behöver gemensamma definitioner, kända källor och en medvetenhet om vilka skillnader vi förenklar när information sammanställs.</p><h3 id="ar-en-databas-en-kalla-till-kunskap" tabindex="-1">Är en databas en källa till kunskap? <a class="header-anchor" href="#ar-en-databas-en-kalla-till-kunskap" aria-label="Permalink to &quot;Är en databas en källa till kunskap?&quot;">​</a></h3><p>Vi kan använda databasen för att ta reda på vilka produkter som har sålts, vilka kunder som finns registrerade och hur lagersaldot förändrats.</p><p>Sådana svar kan vara viktiga underlag för kunskap.</p><p>Men skillnaden mellan <strong>data</strong>, <strong>information</strong> och <strong>kunskap</strong> är inte bara en fråga om tekniska nivåer.</p><p>För att förstå ett resultat behöver vi ofta veta hur uppgifterna samlades in, vilka antaganden som gjordes och vilket sammanhang vi tolkar dem i.</p><p>Bokhandelns databas kan visa att försäljningen av en produkt ökade. Den säger inte automatiskt <em>varför</em>.</p><p>Vi kanske behöver undersöka en kampanj, en recension, en leveransförsening eller något annat som inte finns i databasen.</p><p><strong>SQL hjälper oss att ställa precisa frågor till lagrad information. Att förstå svarens betydelse är ett större arbete.</strong></p><h3 id="vad-aterstar-nar-vi-kan-sql" tabindex="-1">Vad återstår när vi kan SQL? <a class="header-anchor" href="#vad-aterstar-nar-vi-kan-sql" aria-label="Permalink to &quot;Vad återstår när vi kan SQL?&quot;">​</a></h3><p>Vi har lärt oss att skapa tabeller, formulera Queries, modellera relationer, förändra data, skydda information och analysera den.</p><p>Det ger oss många tekniska möjligheter.</p><p>Men innan vi börjar skriva SQL behöver vi fortfarande kunna ställa några enklare frågor:</p><p><strong>Vad är det vi vill beskriva?</strong></p><p><strong>Vad betyder uppgifterna?</strong></p><p><strong>Vilka samband behöver vi bevara?</strong></p><p><strong>Vad behöver vara sant för att informationen ska vara användbar?</strong></p><p><strong>Vilka frågor vill vi kunna besvara – nu och i framtiden?</strong></p><p>Ju bättre vi förstår detta, desto mer meningsfull blir också vår SQL.</p><p>Och när ett informationsbehov förändras behöver vi vara beredda att förändra vår modell, våra regler och ibland också vår uppfattning om vad som är viktigt att registrera.</p><p>Vi började med att konstatera att människor alltid har behövt hålla reda på saker.</p><p>Databaser är ett av våra mest användbara verktyg för det. Men de är fortfarande <strong>verktyg för att beskriva och arbeta med information</strong>.</p><p>De ersätter inte verkligheten, våra beslut eller vårt ansvar att förstå den.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Kan en Query ge ett korrekt resultat som ändå leder till ett felaktigt beslut? Vad skulle det bero på?</li><li>Hur påverkar datamodellen vilka saker vi senare kan förstå – och vilka frågor vi aldrig kommer att kunna besvara?</li><li>Var går gränsen mellan det ansvar vi kan lägga på databasen och det ansvar människor och verksamheter alltid behöver behålla?</li></ol>`,117)])])}const v=e(s,[["render",i]]);export{g as __pageData,v as default};
